package identity

import (
 "crypto/ed25519"
 "crypto/rand"
 "encoding/base64"
 "errors"
 "sync"
 "time"
)

var (
 ErrConnectionUnknown = errors.New("connection unknown")
 ErrConnectionAlreadyAuthenticated = errors.New("connection already authenticated")
 ErrConnectionUnauthenticated = errors.New("connection unauthenticated")
)

type connection struct {
 sessionID string
 peer ed25519.PublicKey
 authenticated bool
}

// TransportAuth models the identity handshake for a future network transport.
// All connection IDs are generated by this registry, never accepted from clients.
type TransportAuth struct {
 mu sync.Mutex
 connections map[string]*connection
 challenges *ChallengeStore
}

func NewTransportAuth(ttl time.Duration,maxChallenges int)(*TransportAuth,error){
 challenges,err:=NewChallengeStore(ttl,maxChallenges)
 if err!=nil{return nil,err}
 return &TransportAuth{connections:make(map[string]*connection),challenges:challenges},nil
}

func (a *TransportAuth) Open(sessionID string,public ed25519.PublicKey)(string,error){
 if sessionID==""||len(public)!=ed25519.PublicKeySize{return "",errors.New("invalid connection identity")}
 random:=make([]byte,32)
 if _,err:=rand.Read(random);err!=nil{return "",err}
 id:=base64.RawURLEncoding.EncodeToString(random)
 a.mu.Lock();defer a.mu.Unlock()
 a.connections[id]=&connection{sessionID:sessionID,peer:append(ed25519.PublicKey(nil),public...)}
 return id,nil
}

func (a *TransportAuth) Challenge(connectionID string)(string,Challenge,error){
 a.mu.Lock();defer a.mu.Unlock()
 c,ok:=a.connections[connectionID]
 if !ok{return "",Challenge{},ErrConnectionUnknown}
 if c.authenticated{return "",Challenge{},ErrConnectionAlreadyAuthenticated}
 return a.challenges.Issue(c.peer,connectionID,c.sessionID)
}

func (a *TransportAuth) Authenticate(connectionID,challengeID string,signature []byte)(string,error){
 a.mu.Lock();defer a.mu.Unlock()
 c,ok:=a.connections[connectionID]
 if !ok{return "",ErrConnectionUnknown}
 if c.authenticated{return "",ErrConnectionAlreadyAuthenticated}
 if err:=a.challenges.Consume(challengeID,c.peer,connectionID,c.sessionID,signature);err!=nil{return "",err}
 fingerprint,err:=Fingerprint(c.peer)
 if err!=nil{return "",err}
 c.authenticated=true
 return fingerprint,nil
}

func (a *TransportAuth) Identity(connectionID string)(sessionID,fingerprint string,err error){
 a.mu.Lock();defer a.mu.Unlock()
 c,ok:=a.connections[connectionID]
 if !ok{return "","",ErrConnectionUnknown}
 if !c.authenticated{return "","",ErrConnectionUnauthenticated}
 fingerprint,err=Fingerprint(c.peer)
 return c.sessionID,fingerprint,err
}

func (a *TransportAuth) Close(connectionID string){
 a.mu.Lock();defer a.mu.Unlock()
 delete(a.connections,connectionID)
}
